-- Study Abroad country content, BATCH 11: Romania, Bulgaria, Croatia, Serbia, Slovakia.
-- Researched from public sources in November 2026 (see backend/TODO_country_tables.md for what still needs checking).
-- Text blocks fill the columns on countries; subject / course rows are linked to subjects / specializations
-- (country_sections.subject_id / specialization_id) so the website links them to those pages.
-- Replaces the earlier '[Sample]' / '[Placeholder]' rows of these 5 countries. Safe to re-run.
-- Requires alembic revision e6a3c9d1f4b7 (alembic upgrade head).
BEGIN;
DELETE FROM country_sections WHERE country_id IN (SELECT id FROM countries WHERE slug IN ('romania', 'bulgaria', 'croatia', 'serbia', 'slovakia'));
UPDATE countries SET why_title = 'Why study in Romania?', why_body = '<p>Romania is an EU country with English-taught medicine, dentistry, pharmacy and engineering degrees at lower tuition than most of Western Europe.</p><ul><li>English-taught medicine and dentistry at public universities</li><li>EU-recognised degrees</li><li>Lower tuition and living costs than most of Europe</li><li>Government scholarships for non-EU students</li></ul>', visa_title = 'Student visa requirements', visa_body = '<p>Non-EU students need a <strong>long-stay study visa</strong> based on a letter of acceptance from the Romanian Ministry of National Education, then a residence permit after arrival.</p><ul><li>Letter of acceptance for studies from the Ministry of National Education, requested through your university</li><li>Proof of payment of at least one year of tuition (EU immigration portal)</li><li>Criminal record certificate and international health insurance</li><li>Apply at the Romanian embassy or consulate in your home country</li><li>Check validity and conversion rules with the embassy: sources disagree on the initial visa length</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official Romanian embassy and your university site before you apply.</em></p>', application_title = 'Application requirements', application_body = '<p>You apply directly to each university. Application windows usually run from spring to mid-July for the autumn intake.</p><ul><li>Academic transcripts and certificates, apostilled</li><li>English proficiency proof</li><li>Entrance exam or file examination, depending on the programme</li><li>Motivation letter for Master''s programmes</li><li>Passport copy and photographs</li><li>Medical certificate</li></ul>', cost_title = 'Cost of studying', cost_body = '<p>Tuition depends on the university and programme.</p><ul><li>English-taught medicine: about €8,500 a year at Craiova and Iași (2025-26 and 2026-27 fee lists); dentistry about €6,500 at Craiova</li><li>Other programmes: roughly €2,500-€5,000 a year (estimate)</li><li>Living costs: about €400-€800 a month (estimate)</li><li>Health insurance is required</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official university site before you apply.</em></p>', eligibility_title = 'Eligibility criteria', eligibility_body = '<p>Requirements depend on the university and level.</p><ul><li><strong>Bachelor''s:</strong> a secondary school certificate; medicine needs biology and chemistry</li><li><strong>Master''s:</strong> a relevant bachelor''s degree</li><li><strong>Language:</strong> IELTS 5.5-6.5 or equivalent for English-taught programmes</li></ul>' WHERE slug = 'romania';
UPDATE countries SET why_title = 'Why study in Bulgaria?', why_body = '<p>Bulgaria is an EU country with low-cost, English-taught medicine, dentistry and pharmacy degrees, plus business, engineering and IT programmes.</p><ul><li>English-taught medicine and dentistry at public medical universities</li><li>EU-recognised degrees</li><li>Low tuition and living costs</li><li>Sofia as a growing tech and business hub</li></ul>', visa_title = 'Student visa requirements', visa_body = '<p>Non-EU students need a <strong>Type D long-stay visa</strong> and then a residence permit from the Migration Directorate. Universities send admission files to the Ministry of Education and Science, which handles the process.</p><ul><li>Admission letter and the Ministry of Education approval</li><li>Passport, accommodation proof, health insurance, proof of funds and medical certificate</li><li>Criminal record certificate for applicants over 18</li><li>Visa fee: €100 or €200, depending on the legal article (non-refundable)</li><li>Processing can take up to 90 days, so apply early</li><li>Register your address within 5 days of arrival</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official Bulgarian embassy and your university site before you apply.</em></p>', application_title = 'Application requirements', application_body = '<p>You apply directly to each university, and documents often need legalisation and an official Bulgarian translation.</p><ul><li>Academic transcripts and certificates, legalised and translated</li><li>English proficiency proof</li><li>Entrance exam in biology and chemistry for medicine</li><li>Motivation letter for Master''s programmes</li><li>Passport copy and photographs</li><li>Medical certificate</li></ul>', cost_title = 'Cost of studying', cost_body = '<p>Tuition depends on the university and programme.</p><ul><li>Sofia University: €3,300 a year for most full-time programmes in 2026-27, with a preparatory language course at €3,500</li><li>Medical University of Sofia (dental medicine in English): €10,000 in years 1-2, €9,000 in years 3-4 and €8,000 in years 5-6 (reported 2026-27); check the MBBS fee with the university</li><li>Living costs: about €400-€800 a month (estimate)</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official university site before you apply.</em></p>', eligibility_title = 'Eligibility criteria', eligibility_body = '<p>Requirements depend on the university and level.</p><ul><li><strong>Bachelor''s:</strong> a secondary school certificate; medicine needs biology and chemistry</li><li><strong>Master''s:</strong> a relevant bachelor''s degree</li><li><strong>Language:</strong> Bulgarian B2 for Bulgarian-taught programmes; English proof for English-taught programmes</li></ul>' WHERE slug = 'bulgaria';
UPDATE countries SET why_title = 'Why study in Croatia?', why_body = '<p>Croatia is an EU country with a long university tradition in Zagreb, a growing number of English-taught programmes, and an attractive coastal lifestyle.</p><ul><li>EU-recognised degrees</li><li>English-taught programmes in medicine, business and engineering</li><li>Moderate costs compared with Western Europe</li><li>Tourism, shipping and tech sectors</li></ul>', visa_title = 'Residence permit requirements', visa_body = '<p>Non-EU students staying over 90 days need a <strong>temporary residence permit for study</strong>. Sources differ on whether you apply at a Croatian diplomatic mission or after arrival, so confirm with the university.</p><ul><li>Proof of enrolment as a full-time student</li><li>Proof of financial means (an exchange-student page reports about €270 a month, which may be out of date)</li><li>Accommodation proof and valid health insurance</li><li>Permit can be issued for up to two years or the length of studies if shorter</li><li>You cannot attend classes until the permit is issued</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official Croatian police administration and your university site before you apply.</em></p>', application_title = 'Application requirements', application_body = '<p>You apply directly to each university, and some programmes use national exams.</p><ul><li>Academic transcripts and certificates, apostilled</li><li>English proficiency proof for English-taught programmes</li><li>Entrance exam for medicine and some other programmes</li><li>Motivation letter for Master''s programmes</li><li>Passport copy and photographs</li></ul>', cost_title = 'Cost of studying', cost_body = '<p>Fees are set by each institution.</p><ul><li>Public universities: roughly €1,000-€5,000 a year for non-EU students (indicative guide range)</li><li>English-taught medicine: roughly €8,000-€12,000 a year (indicative)</li><li>Living costs: about €500-€900 a month (estimate)</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official university site before you apply.</em></p>', eligibility_title = 'Eligibility criteria', eligibility_body = '<p>Requirements depend on the university and level.</p><ul><li><strong>Bachelor''s:</strong> a secondary school certificate; medicine needs biology and chemistry</li><li><strong>Master''s:</strong> a relevant bachelor''s degree</li><li><strong>Language:</strong> IELTS 5.5-6.5 or equivalent for English-taught programmes</li></ul>' WHERE slug = 'croatia';
UPDATE countries SET why_title = 'Why study in Serbia?', why_body = '<p>Serbia has long-established universities, low costs and more than 170 programmes taught fully or partly in English, including medicine.</p><ul><li>English-taught programmes at public universities</li><li>Low tuition and living costs</li><li>Strong in medicine, engineering, IT and arts</li><li>Central Balkan location</li></ul>', visa_title = 'Visa and residence permit', visa_body = '<p>Students first obtain a <strong>Type D long-stay visa</strong> and then apply for <strong>temporary residence for study</strong> after arrival.</p><ul><li>Admission letter and certificates from the university and the Ministry of Education</li><li>Travel medical insurance: the Ministry of Foreign Affairs recommends at least €20,000 cover</li><li>Register with the police or local authorities within 24 hours of arrival</li><li>Temporary residence for study reportedly allows up to 16 hours of work a week</li><li>Residence can be extended after studies for a limited period (Niš guidance)</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official Serbian embassy, welcometoserbia.gov.rs and your university site before you apply.</em></p>', application_title = 'Application requirements', application_body = '<p>You apply directly to each faculty. Documents often need an apostille and translation.</p><ul><li>Academic transcripts and certificates, apostilled</li><li>English or Serbian language proof</li><li>Entrance exam for medicine and some faculties</li><li>Motivation letter for Master''s programmes</li><li>Passport copy and photographs</li></ul>', cost_title = 'Cost of studying', cost_body = '<p>Each university sets its own fees.</p><ul><li>Overall range for international students: about €750-€20,000 a year, with medicine at the top (Study in Serbia)</li><li>Living costs: about €400-€700 a month (estimate)</li><li>Health insurance is required</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official faculty site before you apply.</em></p>', eligibility_title = 'Eligibility criteria', eligibility_body = '<p>Requirements depend on the university and level.</p><ul><li><strong>Bachelor''s:</strong> a secondary school certificate; medicine needs biology and chemistry</li><li><strong>Master''s:</strong> a relevant bachelor''s degree</li><li><strong>Language:</strong> English proof for English-taught programmes; Serbian for local programmes</li></ul>' WHERE slug = 'serbia';
UPDATE countries SET why_title = 'Why study in Slovakia?', why_body = '<p>Slovakia is an EU country with affordable, English-taught medicine, dentistry, veterinary and engineering programmes at public universities such as Comenius University.</p><ul><li>English-taught medicine and dentistry</li><li>EU-recognised degrees</li><li>Lower costs than Western Europe</li><li>Central European location, close to Vienna and Budapest</li></ul>', visa_title = 'Visa and residence permit', visa_body = '<p>Non-EU students apply for a <strong>Type D long-term study visa</strong> and then a <strong>temporary residence permit</strong> at the local Foreign Police Department after arrival.</p><ul><li>Admission letter and proof of tuition or funds</li><li>Health insurance, accommodation proof and criminal record certificate</li><li>Start early: the EU portal says the process may take 2-4 months</li><li>Some universities, such as Prešov (2026/27), require booking an appointment before applying; check your faculty</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official Slovak embassy and your university site before you apply.</em></p>', application_title = 'Application requirements', application_body = '<p>You apply directly to each faculty. For Comenius medicine, applications for the 2027/28 intake run 15 November to 31 December 2026, with online exams in March, June and August (faculty site; confirm).</p><ul><li>Academic transcripts and certificates, apostilled</li><li>English proficiency proof</li><li>Entrance exam in biology and chemistry for medicine; an IB Diploma of at least 33 points is accepted at Comenius (2027/28)</li><li>Motivation letter for Master''s programmes</li><li>Passport copy and photographs</li></ul>', cost_title = 'Cost of studying', cost_body = '<p>Fees are set by the faculty.</p><ul><li>Medicine in English: often €9,000-€12,000 a year at public universities (third-party guide)</li><li>Other programmes: roughly €2,000-€5,000 a year (estimate)</li><li>Living costs: about €500-€800 a month (estimate)</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official faculty site before you apply.</em></p>', eligibility_title = 'Eligibility criteria', eligibility_body = '<p>Requirements depend on the university and level.</p><ul><li><strong>Bachelor''s:</strong> a secondary school certificate; medicine needs biology and chemistry</li><li><strong>Master''s:</strong> a relevant bachelor''s degree</li><li><strong>Language:</strong> IELTS 5.5-6.5 or equivalent for English-taught programmes</li></ul>' WHERE slug = 'slovakia';
COMMIT;
